ch(b,new Long[]{700002L},true,1);s.batch(a,new Long[]{700002L},false,1);check(s.userRoles(700002).contains(b)&&!s.userRoles(700002).contains(a),"batch remove preserves other roles");reject(()->s.bind(1812120000000000L,new Long[]{},1),"super administrator binding protected");reject(()->s.grant(a,new Long[]{999999999L},1),"unknown menu rejected");reject(()->s.saveRole(null,"bad","admin","0","",1),"reserved admin role key rejected");check(db.queryForObject("select count(*) from sys_role_menu where role_id=? and menu_id=8100000",Integer.class,a)>0,"menu ancestors included");check(!s.audit().isEmpty(),"authorization audit saved");
